// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · İstatistiksel yanılgılar ve veri okuryazarlığı (zor).
const ozStatistics13Zor = <(String, String, List<String>, String)>[
  ('Hilesiz bir para 100 kez atıldığında dizide aynı yüzün en az 5 kez art arda geldiği bir bölüm bulunma olasılığı yaklaşık kaçtır?', 'Yaklaşık %97', ['Yaklaşık %50, çünkü yazı ile tura eşit olasıdır', 'Yaklaşık %25', 'Yaklaşık %5'], 'Dinamik programlama ile hesaplanan bu olasılık yaklaşık 0,97\'dir. Uzun diziler, sezgilerin beklediğinden çok daha sık uzun seriler içerir.'),
  ('Sayısal çekilişte çok sayıda oyuncunun 1-2-3-4-5-6 gibi görünür örüntüleri seçtiği bilinmektedir. Bu bilgi, böyle bir kombinasyonu oynamak için hangi çıkarımı destekler?', 'Olasılık değişmez, ama kazanç daha çok kişiyle paylaşılır', ['Kazanma olasılığı düşer, çünkü örüntülü kombinasyonlar nadiren çekilir; bu yüzden hiç oynanmamalıdır', 'Kazanma olasılığı artar, çünkü çok kişi aynı kombinasyonu oynamaktadır', 'Kazanma olasılığı aynı kalır ve ikramiyenin paylaşılma riski de değişmez'], 'Çekilişin sonucu bağımsız ve eşit olasılıklıdır. Fakat popüler kombinasyonlar seçildiğinde kazanç daha çok kişiye bölüneceği için beklenen ödül düşer.'),
  ('Hilesiz bir paranın atış sayısı 100\'den 10.000\'e çıktığında \'yazı sayısı ile tura sayısı arasındaki mutlak fark\' ve \'yazı oranının 0,5\'ten sapması\' için genel olarak hangisi beklenir?', 'Mutlak fark genellikle büyür, oranın sapması ise küçülür', ['Mutlak fark da oran sapması da sıfıra iner, çünkü büyük sayılar yasası farkı tamamen yok eder', 'Mutlak fark küçülür, oran sapması ise büyür', 'Her ikisi de atış sayısından bağımsız kalır'], 'Mutlak sapma yaklaşık √n ile büyür, oran sapması ise yaklaşık 1/√n ile küçülür. Büyük sayılar yasası oranın yakınsamasını söyler, farkın sönmesini değil.'),
  ('Bir iş kitabı, yıllarca başarılı olan şirketlerin ortak özelliklerini inceleyip \'bu özellikler başarının nedenidir\' diyor. Aynı özelliklere sahip olup batmış şirketler incelenmemiştir. Bu çalışmanın temel kusuru hangisidir?', 'Aynı özelliklere sahip batmış şirketlere bakılmadığından özelliğin ayırt ediciliği bilinemez', ['Başarılı şirketlerin sayısının çok az olması, çünkü başarı yalnız başarılı örneklerden anlaşılır', 'Şirketlerin yalnızca ulusal ölçekte incelenmiş olması', 'Başarı ölçütünün sayısal bir değer olarak verilmemiş olması'], 'Başarıyı açıklamak için başarısızları da içeren bir karşılaştırma gerekir. Yalnızca hayatta kalanlara bakıldığında ortak özelliklerin başarısızlarda da aynı sıklıkta olması olasılığı gözden kaçar.'),
  ('İkinci Dünya Savaşı sonrasında bir araştırmacı, dönen bombardıman uçaklarındaki hasar bölgelerinin sayısını çıkarıp kanatlardaki hasarın motorlardan çok olduğunu fark ediyor. Hayatta kalma yanlılığı bilen bir analist neden motoru güçlendirmeyi önerebilir?', 'Motorundan vurulan uçaklar geri dönemediği için motor hasarı verisi eksiktir', ['Motor hasarının hiç yaşanmadığı kesin olduğu için, çünkü motorlar hiç hasar görmez', 'Kanat hasarının uçuşu hiç etkilemediği için', 'Motorların kanatlardan daha ucuz güçlendirilebildiği için'], 'Geri dönen uçaklar hasara rağmen yaşayanlardır; motoru vurulanlar dönmemiştir. Bu yüzden motor bölgesinde delik olmaması, orası vurulursa uçağın düşmesinin işaretidir.'),
  ('Bir üniversite, yalnızca bursu hak eden öğrencilerin mezuniyet notlarını inceliyor ve burs sınavı puanı ile mezuniyet notu arasında hiçbir ilişki bulamıyor. Burs sınavının mezuniyet başarısını yordamadığı sonucuna varmak neden güvensizdir?', 'Örneklem yüksek puanlılarla sınırlıdır; aralık daralması ilişkiyi zayıflatır', ['Mezuniyet notlarının sayısal olmaması, çünkü ilişki yalnız sayısal veride ölçülür', 'Burs sınavının her zaman geçerli bir ölçü olması', 'Öğrenci sayısının çok fazla olması'], 'Yalnızca yüksek puanlıların incelenmesi değişkenin aralığını daraltır (aralık kısıtlaması). Bu durumda gerçekte var olan ilişki bile zayıf ya da yok gibi görünebilir.'),
  ('Bir gözlemsel çalışmada yaş, cinsiyet ve gelir istatistiksel olarak ayarlandıktan sonra bile sonuç yanıltıcı olabilir. Bunun sorumlusu olan \'artık karıştırıcılık\' ne demektir?', 'Ölçülmeyen veya kusurlu ölçülen etkenlerin kalan karıştırıcı etkisi', ['Ayarlama yapılan etkenlerin yanlışlıkla iki kez hesaplanması, çünkü bu hata sonucu iki katına çıkarır', 'Örneklem sayısının fazla olması', 'Sonuç değişkeninin sayısal olması'], 'İstatistiksel ayarlama yalnızca ölçülmüş değişkenleri düzeltir; ölçülemeyen veya yaklaşık ölçülen etkenler kalıntı bir yanlılık bırakır.'),
  ('1973\'te Kaliforniya Üniversitesi Berkeley kampüsünün lisansüstü başvurularında erkeklerin genel kabul oranı yaklaşık %44, kadınlarınki yaklaşık %35 idi; ancak bölümler tek tek incelenince kadınlar aleyhine bir fark görülmedi. Bu tablonun en olası açıklaması nedir?', 'Kadınlar, kabul oranı düşük olan bölümlere orantısız biçimde çok başvurmuştu', ['Her bölümde kabul komitelerinin kadın adaylara kasıtlı olarak daha yüksek puan vermesi', 'Başvuru sayılarının erkeklerde kadınlardan çok daha az olması ve oranların bu nedenle yanıltıcı çıkması', 'Bölüm bazındaki oranların hatalı hesaplanmış olması ve gerçek farkın bütün bölümlerde gizlenmesi'], 'Birleşik oranlar bölüm karışımından etkilenmişti: kadın başvuruları zor bölümlerde yoğunlaşmıştı. Bu, Simpson paradoksunun en ünlü gerçek örneklerinden biridir.'),
  ('Böbrek taşı tedavisinde A yöntemi küçük taşlarda 87 hastanın 81\'inde, büyük taşlarda 263 hastanın 192\'sinde; B yöntemi küçük taşlarda 270 hastanın 234\'ünde, büyük taşlarda 80 hastanın 55\'inde başarılı olmuştur. Taş büyüklüğü ayrılmadan toplam başarı oranları nedir?', 'A yaklaşık %78, B yaklaşık %83', ['A yaklaşık %83, B yaklaşık %78, çünkü A yöntemi her grupta üstündür', 'A ve B için de yaklaşık %80', 'A yaklaşık %93, B yaklaşık %87'], 'A: (81+192)/(87+263) = 273/350 = %78; B: (234+55)/(270+80) = 289/350 = %82,6. A her taş grubunda üstün olduğu hâlde toplamda geride kalır; Simpson paradoksu.'),
  ('Bir üniversitede X bölümüne erkeklerin 60/80\'i, kadınların 18/20\'si; Y bölümüne erkeklerin 4/20\'si, kadınların 30/100\'ü kabul ediliyor. Bölüm ayrımı yapılmadan toplam kabul oranlarının karşılaştırılması hakkında hangisi doğrudur?', 'Erkeklerde toplam oran %64, kadınlarda %40 olur; oysa kadınlar her bölümde öndedir', ['Kadınların toplam oranı daha yüksektir, çünkü kadınlar her bölümde öndedir', 'İki cinsin toplam oranı eşit çıkar, çünkü bölüm oranları birbirini götürür', 'Erkeklerin toplam oranı %75, kadınlarınki %83\'tür, yani bölüm oranlarının ortalaması alınmıştır'], 'Erkek: (60+4)/(80+20) = %64; kadın: (18+30)/(20+100) = %40. Kadınların başvurusu kabulü düşük Y bölümünde yığıldığı için toplam sıra tersine döner.'),
  ('Bir tedavide hastalar önce tansiyonlarına göre iki gruba ayrılıyor ve tedavinin etkisi her tansiyon grubunda ayrı ayrı inceleniyor. Ancak tansiyon, tedavinin sonucu olan bir aracı değişkendir. Bu durumda gruplamanın sonucu ne olur?', 'Tedavinin etkisinin bir bölümü ayrıştırılarak gizlenir ve toplam etki hafife alınabilir', ['Karıştırıcı etki tümüyle ortadan kalkar ve gerçek etki kusursuz ölçülür, çünkü gruplama her yanlılığı giderir', 'Örnek büyüklüğü iki katına çıktığı için kesinlik mutlaka artar', 'Tedavinin her zaman zararlı olduğu görülür'], 'Tedavinin sonucu olan bir değişkene göre koşullandırmak, nedensel yolun bir kısmını keser. Bu nedenle ayrıştırma her durumda \'daha doğru\' değildir; grup değişkeninin nedensel rolüne bakılmalıdır.'),
  ('Bir sınavda ortalaması 100, standart sapması 15 olan iki sınav arasındaki korelasyon 0,6\'dır. İlk sınavda 130 alan bir öğrencinin ikinci sınavdaki beklenen puanı hangisine en yakındır?', '118', ['130, çünkü ilk puan ikincide aynen korunur', '124', '106'], 'Standart puan 2 olup beklenen standart puan 0,6 × 2 = 1,2\'dir; 100 + 1,2 × 15 = 118. Korelasyon 1\'den küçük olduğu için sonuç ortalamaya doğru çekilir.'),
  ('Bir okul, sınavda en düşük %10\'luk dilimdeki öğrencilere telafi kursu açıyor ve bu öğrencilerin ikinci sınavda ortalama olarak yükseldiğini görüyor. Kursun etkisini ayırt etmek için en gerekli ek bilgi hangisidir?', 'Kursa alınmayan benzer düşük puanlıların ikinci sınav sonuçları', ['Kursun kaç saat sürdüğü ve dersleri hangi öğretmenin verdiği, ve hangi gün yapıldığı', 'Öğrencilerin sınıf mevcutlarına göre sıralaması', 'Sınavın yapıldığı gün hava durumu'], 'En düşük puanlılar kısmen şanssız oldukları için kursa girmese de ortalamaya doğru yükselirdi. Etkiyi görmek için benzer ama kursa gitmeyen bir karşılaştırma grubu gerekir.'),
  ('Bir hastalığın bir grupta görülme olasılığı %40, başka bir grupta %20\'dir. Risk oranı (göreli risk) 2 iken olasılıkların odds oranı kaçtır?', 'Yaklaşık 2,67', ['Tam olarak 2, çünkü bu iki ölçü her zaman aynıdır', 'Yaklaşık 1,5', 'Yaklaşık 4'], 'Odds oranı = (0,4/0,6) / (0,2/0,8) = 0,667 / 0,25 ≈ 2,67\'dir. Olay yaygın olduğunda odds oranı göreli riski abartır; olay nadirse ikisi birbirine yaklaşır.'),
  ('Bir kanser taramasında hastalar teşhisten sonra \'5 yıllık sağ kalım\' ile izleniyor; tarama sayesinde hastalık 3 yıl daha erken tanınıyor, ancak ölüm yaşı değişmiyor. Sağ kalım istatistiği bu durumda nasıl değişir?', 'Tanı öne çekildiği için sağ kalım süresi yapay uzar', ['Sağ kalım süresi yapay biçimde kısalmış görünür, çünkü tanı erken konunca izlem kısalır', 'Sağ kalım süresi hiç değişmez', 'Sağ kalım süresi hesaplanamaz olur'], 'Tanı anı öne çekildiği için aynı ölüm tarihine kadar geçen süre uzar. Bu önyargıya öncül zaman (lead-time) yanlılığı denir; tarama etkisi için ölüm oranlarına bakılmalıdır.'),
  ('Bir tarama programı, yavaş büyüyen ve kişiyi hiç öldürmeyecek tümörleri de buluyor. Bu durum tarama programının başarı oranını (teşhis edilenlerin sağ kalımını) nasıl etkiler?', 'Sağ kalım oranı yüksek görünür; zararsız vakalar da sayılır', ['Sağ kalım oranı düşük görünür, çünkü zararsız vakalar ölmez, ama gerçek ölüm sayısı da artar', 'Sağ kalım oranı değişmez, çünkü yavaş tümörler sayılmaz', 'Sağ kalım oranı ancak ölenlerin yaşına göre hesaplanabilir'], 'Aşırı tanı, hiç ilerlemeyecek hastalıkları \'hasta\' olarak ekler ve bu kişiler uzun yaşar. Sağ kalım oranı iyileşmiş görünür, oysa ölüm sayısı azalmamış olabilir.'),
  ('Bir kentte 5 milyon yetişkin yaşıyor ve olay yerindeki DNA profili rastgele birinde milyonda bir olasılıkla bulunuyor. Başka hiçbir delil olmadan, kenti tarayıp eşleşen birini bulursanız bu kişinin gerçek fail olma olasılığı yaklaşık kaçtır?', 'Yaklaşık 1/6', ['Yaklaşık 999.999/1.000.000', 'Yaklaşık 1/2', 'Yaklaşık 1/5.000.000'], 'Şansla yaklaşık 5 kişi eşleşir, faille birlikte 6 eşleşen olur; eşleşenlerden biri suçludur. Bu nedenle olasılık yaklaşık 1/6\'dır; DNA tek başına kesin suçlama yapmaz.'),
  ('Savunma avukatı \'Kentte DNA\'sı eşleşen yaklaşık 6 kişi var, öyleyse sanığın suçlu olma olasılığı yalnızca 1/6\'dır ve delil değersizdir\' diyor. Bu savunma neden yanıltıcıdır?', 'Delil, şüpheli sayısını milyonlardan 6\'ya indirmiştir', ['Delilin değerli olması, eşleşenlerin sayısının tek olmasına bağlıdır', 'Altı eşleşen kişi olması sanığın masum olduğunu kanıtlar', 'DNA eşleşmesi hiçbir zaman delil olarak kullanılamaz'], 'Savunma avukatı yanılgısı, delilin önsel durumdan sonsal duruma getirdiği değişimi görmezden gelir. Şüpheli kümenin 5 milyondan 6\'ya inmesi çok güçlü bir kanıttır, ancak tek başına kesin değildir.'),
  ('1950\'lerde ABD hava kuvvetleri pilotlarından 4.063 kişinin on boyut ölçümü alındığında, on ölçümün hepsinde \'ortalama\' sayılabilecek aralığa düşen pilot çıkmamıştır. Bu bulgu \'ortalamaya göre tasarım\' için neyi gösterir?', 'Çok boyutta birden ortalama olan kişi neredeyse yoktur', ['Pilotların ölçümlerinin yanlış alındığını', 'Ortalama boyutların hiçbir zaman hesaplanamadığını', 'Pilotların vücut ölçülerinin tamamen birbirine eşit olduğunu'], 'Her boyutta ortalamaya yakın olma olasılığı küçük olduğundan, hepsinde aynı anda ortalamaya yakın olan kişi çok nadirdir. Bu nedenle uyarlanabilir tasarım, tek bir ortalama kişiye göre tasarımdan daha iyidir.'),
  ('Bir araştırmacı veri toplarken her gün analiz yapıyor ve p < 0,05 çıktığında örnek toplamayı bırakıyor. Hiçbir etki yokken bu yöntem uzun vadede ne yapar?', 'Yanlış pozitif oranını nominal %5\'in çok üzerine çıkarır', ['Yanlış pozitif oranını %5\'in altına indirir, çünkü sürekli bakmak şansı azaltır', 'Yanlış pozitif oranını hiç değiştirmez', 'Yanlış negatif oranını sıfıra indirir'], 'Sürekli bakıp anlamlı çıkınca durmak, şansla eşiği aşma fırsatını artırır. Durma kuralı önceden belirlenmediğinde p-değeri geçerli hata oranını vermez.'),
  ('Aynı veri setiyle analizde aykırı değer çıkarma, değişken dönüştürme ve alt grup seçme gibi yüzlerce makul yol vardır; araştırmacı yalnızca anlamlı sonuç veren yolu raporluyor. İstatistikçi Andrew Gelman\'ın bu duruma verdiği ad nedir?', 'Dallanan yollar bahçesi', ['Büyük sayılar yasası, yani oranların uzun vadede sabitlenmesi', 'Kümelenme yanılsaması', 'Ekolojik yanılgı'], 'Her analiz kararı, veriye bakıldıktan sonra verilirse, ortada gerçekte tek bir test değil çok sayıda örtük test vardır. Bu, p-değerlerini olduğundan küçük gösterir.'),
  ('1988\'deki ISIS-2 çalışmasının yazarları, aspirinin kalp krizi sonrası yararlı olduğunu gösterirken, hastaları burçlarına göre ayırdıklarında İkizler ve Terazi burçlarında aspirinin zararlı göründüğünü bildirdi. Bu gözlem neyi örnekler?', 'Çok sayıda alt grup analizinde anlamsız ayrımlarda da şansla etki çıkabileceğini', ['Burçların kalp hastalığı üzerinde gerçek bir etkisi olduğunu, çünkü burçlar gerçek bir etken taşır', 'Aspirinin yalnızca bazı burçlarda işe yaradığını', 'Yıldızlara göre örneklem seçmenin iyi bir yöntem olduğunu'], 'Yazarlar bu uyarıyı bilerek yaptı: anlamsız bir ölçütle bile alt gruplara bölünce yapay \'bulgular\' görülebilir. Alt grup bulguları genel çalışma sonucundan çok daha az güvenilirdir.'),
  ('A grubunda tedavi etkisi anlamlı (p = 0,03), B grubunda anlamsız (p = 0,20) bulunuyor ve \'tedavi A\'da işe yarıyor, B\'de yaramıyor\' deniyor. Bu çıkarımdaki temel hata nedir?', 'Gruplar arası farkın kendisi test edilmemiştir', ['İki grubun ayrı ayrı test edilemeyeceği', 'p değerlerinin hiçbir zaman karşılaştırılamayacağı', 'B grubunda p değerinin 0,20 olamayacağı'], 'Etki iki grupta benzer olup yalnızca kesinliği (örneklem büyüklüğü) farklı olabilir. Gruplar arası farkı doğrudan sınayan bir etkileşim testi gerekir.'),
  ('Düşük güçlü küçük çalışmalar arasında yalnızca anlamlılık eşiğini geçenler yayımlanıyor. Yayımlanan bu çalışmaların bildirdiği etki büyüklükleri gerçek etkiyle karşılaştırıldığında genellikle nasıldır?', 'Gerçek etkiden büyüktür; buna kazananın laneti denir', ['Gerçek etkiden küçüktür, çünkü küçük çalışmalar etkiyi hafife alır', 'Gerçek etkiyle tam olarak aynıdır', 'Gerçek etki hakkında hiçbir sapma taşımaz'], 'Küçük örneklemde eşiği geçmek için gözlenen etkinin şansla da büyük olması gerekir. Seçilen çalışmaların etki tahminleri bu nedenle yukarı doğru yanlıdır.'),
  ('Psikolog Peter Wason\'un 2-4-6 görevinde katılımcılara \'2-4-6\' üçlüsünün gizli bir kurala uyduğu söylenip kuralı bulmak için yeni üçlüler denemeleri isteniyor. Çoğu kişi 8-10-12 gibi kuralını destekleyecek üçlüleri deniyor. Gerçek kural \'artan herhangi üç sayı\' idi. Bu görev neyi gösterir?', 'Kendi hipotezini doğrulayan örnekleri aradıklarını', ['İnsanların sayıları ezberlemekte zorlandığını, çünkü üçlüler hep kolay hatırlanır', 'Gizli kuralların hiçbir zaman bulunamayacağını', 'Katılımcıların matematikte yetersiz olduğunu'], 'Doğrulayıcı üçlüler her zaman \'evet\' cevabı alır ve hipotezi ayırt etmez. Yalnızca \'1-2-3\' ya da \'10-6-2\' gibi kuralı çürütebilecek denemeler yanlış hipotezi açığa çıkarır.'),
  ('Masada E, K, 4 ve 7 yazan dört kart var; her kartın bir yüzünde harf, diğerinde sayı var. \'Bir kartın bir yüzünde sesli harf varsa diğer yüzünde çift sayı vardır\' kuralını sınamak için hangi kartlar çevrilmelidir?', 'E ve 7', ['E ve 4', 'Yalnızca E', 'K ve 4'], 'E\'nin arkası tek çıkarsa kural çürür; 7\'nin arkası sesli harf çıkarsa kural çürür. 4\'ün arkasının ne olduğu kuralı sınamaz; çoğu insan doğrulayıcı kartı (4) seçer.'),
  ('Tversky ile Kahneman\'ın 1981 \'Asya hastalığı\' deneyinde 600 kişiyi tehdit eden bir salgında, \'program A ile 200 kişi kurtarılır\' seçeneği \'program B ile 1/3 olasılıkla 600 kişi kurtulur\' seçeneğine tercih edilirken, aynı seçenekler \'A ile 400 kişi ölür\' diye sunulunca insanlar B\'yi seçti. Bu deney neyi gösterir?', 'Eşdeğer seçenekler kazanç ya da kayıp çerçevesinde sunulunca tercihler değişir', ['İnsanların her zaman riskten kaçındığını', 'Programlar arasında gerçek bir kurtulma farkı olduğunu, çünkü A\'nın beklenen kurtulan sayısı B\'den fazladır', 'Kişilerin sayıları hiç hesaplayamadığını'], 'Her iki sunumda da A\'nın beklenen kurtulanı 200, B\'ninki 600 × 1/3 = 200\'dür. Tercihin çerçeveye bağlı olarak tersine dönmesi, çerçeveleme etkisini kanıtlar.'),
  ('1982\'de McNeil ve arkadaşları, akciğer kanseri için ameliyat ve ışın tedavisi seçeneklerini doktorlara \'ameliyattan sonra bir yıl hayatta kalma %68\' ya da \'ameliyatta ölüm %32\' biçiminde sundu. Doktorların ameliyat tercihi iki sunumda nasıl değişti?', 'Hayatta kalma çerçevesinde ameliyat tercihi belirgin biçimde daha yüksekti', ['Ölüm çerçevesinde ameliyat tercihi daha yüksekti, çünkü ölüm olasılığı daha çarpıcı gelir', 'Tercih iki çerçevede de aynıydı', 'Doktorlar hiçbir çerçevede ameliyatı seçmedi'], 'Aynı bilgi ölüm oranı yerine yaşama oranı olarak anlatılınca uzman hekimler bile farklı seçti. Çerçeveleme, bilgili karar vericileri de etkiler.'),
  ('Tversky ve Kahneman\'ın 1974 deneyinde katılımcılar önce 0-100 arasında şansla 10 ya da 65 gösteren bir çarkı çevirdi; ardından Birleşmiş Milletler\'deki Afrika ülkelerinin oranını tahmin ettiler. Çarkta 10 görenlerin tahmin ortancası yaklaşık 25, 65 görenlerinki yaklaşık 45 oldu. Bu deney neyi göstermektedir?', 'Alakasız sayının bile tahmini kendine çektiğini', ['Katılımcıların Afrika ülkelerini bildiğini', 'Çarkın şansla yüksek çıkmasının tahmin doğruluğunu artırdığını', 'İnsanların sayısal tahmin yapamadığını'], 'Çark sonucunun tahminle hiçbir mantıksal ilişkisi yoktu; yine de tahminler çıpaya doğru kaydı. Çıpalama, alakasız sayıların bile yargıyı etkileyebildiğini gösterir.'),
  ('Lichtenstein ve arkadaşlarının 1978 çalışmasında katılımcılar, cinayet ve kasırga gibi dramatik ölüm nedenlerinin sıklığını abartırken, diyabet ve inme gibi sıradan nedenlerin sıklığını olduğundan az tahmin etti. Bu eğilim hangi sezgisel kısayolla açıklanır?', 'Mevcudiyet sezgisi; kolay akla gelen olaylar sık sanılır', ['Çıpalama; ilk duyulan sayı yargıyı belirler', 'Çerçeveleme; sunum biçimi tercihi değiştirir', 'Doğrulama yanlılığı; inançlara uyan veri seçilir, ve karşıt kanıt görmezden gelinir'], 'Medyada sık yer alan, çarpıcı ölüm nedenleri hafızada daha erişilebilir olduğu için sıklıkları abartılır. Kolay hatırlanmak, gerçekten sık olmakla aynı şey değildir.'),
  ('İngilizce\'de r harfiyle başlayan kelimelerin mi, yoksa üçüncü harfi r olan kelimelerin mi daha çok olduğu sorulduğunda çoğu kişi r ile başlayanları seçiyor; oysa üçüncü harfi r olan kelimeler daha fazladır. Bu yanlış sezgi neden kaynaklanır?', 'İlk harfle kelime hatırlamak kolaydır, bu yüzden örnekler daha erişilebilirdir', ['Üçüncü harfi r olan kelimelerin hiç bulunmamasından, çünkü bu kelimeler sözlüklerde yer almaz', 'Kelimelerin alfabetik sıraya göre sayılmamasından', 'r harfinin diğer harflerden hep sık kullanılmasından'], 'Kelimeleri ilk harfle aramak kolaydır; bu nedenle ilk harfi r olan kelimeler daha çok akla gelir ve sıklıkları abartılır. Mevcudiyet sezgisi, olasılık yargısını çarpıtır.'),
  ('1999\'da bir çalışma, gece lambası açık odada uyuyan çocuklarda miyopi görülme oranının daha yüksek olduğunu bildirdi. Sonraki bir çalışma, miyopik anne babaların hem çocuklarını lambayla yatırmaya hem çocuklarına miyopiyi aktarmaya yatkın olduğunu gösterdi. Bu gelişme neyi örnekler?', 'İlişkiyi ortak neden (anne baba miyopisi) yaratmıştır', ['Lambanın doğrudan miyopiye yol açtığını kesinleştirdiğini', 'Miyopinin çocuklarda hiçbir zaman görülmediğini', 'Gece lambalarının hiçbir koşulda ölçülemeyeceğini'], 'Ortak bir neden iki değişkeni birlikte değiştirince aralarında sahte bir nedensellik görünür. Karıştırıcı kontrol edilince ilişki zayıfladı.'),
  ('100 farklı değişkenin tüm çiftleri arasında korelasyon testi yapılıyor ve değişkenlerin hiçbiri gerçekte ilişkili değil. %5 düzeyinde yanlış pozitif beklenirse şansla \'anlamlı\' çıkması beklenen çift sayısı yaklaşık kaçtır?', 'Yaklaşık 248', ['Yaklaşık 5', 'Yaklaşık 50', 'Yaklaşık 4.950'], '100 değişkenin ikili kombinasyon sayısı C(100, 2) = 4950\'dir; bunların %5\'i, yani yaklaşık 247,5\'i şansla anlamlı çıkar. Büyük veri taramaları bu nedenle sahte ilişkilerle doludur.'),
  ('İşgücünde 100 kişiden 10\'u işsizdir. İşsiz olan 5 kişi iş aramaktan vazgeçerek işgücünün dışına çıkıyor, diğer herkes aynı kalıyor. İşsizlik oranı ne olur?', '%5,3\'e düşer; kimse iş bulmamış olsa da', ['%5\'e düşer; çünkü 5 kişi işsiz sayılmaz', '%10\'da kalır; çünkü hiçbir şey değişmemiştir', '%15\'e çıkar; çünkü işgücü küçülmüştür'], 'Yeni işsiz sayısı 5, işgücü 95\'tir; 5/95 ≈ %5,3. Oran, payı ve paydayı değiştiren bir tanım etkisiyle düşmüş, ama kimse iş bulmamıştır.'),
  ('Bir ülkenin cari fiyatlarla GSYH\'si bir yılda %30 artıyor ve aynı yıl genel fiyat artışı %20\'dir. Reel büyüme yaklaşık kaçtır?', 'Yaklaşık %8,3', ['Yaklaşık %10, çünkü enflasyon çıkarılır', 'Yaklaşık %50', 'Yaklaşık %25'], 'Reel büyüme 1,30 / 1,20 − 1 ≈ 0,083\'tür. Nominal büyüme enflasyondan arındırılmadan üretimin gerçek artışı olarak yorumlanmamalıdır.'),
  ('Bir anketin \'hata payı ±3\' olarak bildirilmesi, sonucun hangi tür hatalardan arınmış olduğu anlamına gelir?', 'Yalnızca örnekleme değişkenliğini ifade eder', ['Bütün yanlılık türlerinden; hata payı küçükse ölçüm kusursuzdur', 'Yalnızca soru ifadesi yanlılığından arınmıştır', 'Yalnızca yanıtsızlık yanlılığından arınmıştır'], 'Bildirilen hata payı, rastgele örneklemden doğan şansa bağlı belirsizliği ölçer. Kapsam hatası, yanıtsızlık ve soru ifadesi gibi sistematik hataları kapsamaz.'),
  ('19 Ekim 1987\'de bir borsa endeksi tek günde yaklaşık %22 düştü; bu düşüş, o dönemdeki günlük değişim dağılımı normal kabul edilirse 20\'den fazla standart sapma uzaklıktaydı. Bu durum normal modelin ne açıdan yetersiz olduğunu gösterir?', 'Gerçek getiriler normalden çok daha sık aşırı değer alır', ['Gerçek getirilerin aşırı değer hiç almaması', 'Normal dağılımın borsada ancak yılda bir kez kullanılabilmesi', 'Standart sapmanın hiçbir veri için hesaplanamaması'], 'Normal modelde 20 standart sapma uzaklıktaki bir olayın olasılığı pratikte sıfırdır; yine de gerçekleşmiştir. Finansal getirilerde kalın kuyruklar, riski düşük tahmin eden normal varsayımı çürütür.'),
  ('Bir kişi, yılda 156 kez (haftada 3) her biri binde 1 ölüm riski taşıyan bir faaliyet yapıyor ve riskler bağımsız kabul ediliyor. Yıllık toplam ölüm riski yaklaşık kaçtır?', 'Yaklaşık %14,5', ['Yaklaşık %0,1, çünkü risk haftalık toplanmaz', 'Yaklaşık %156', 'Yaklaşık %1,5'], 'Hayatta kalma olasılığı 0,999^156 ≈ 0,855\'tir; ölüm riski yaklaşık %14,5\'tir. Her seferinde çok küçük görünen risk tekrarlandıkça belirgin hâle gelir.'),
  ('A grubunun puanları 50, 60, 70, 80 (ortalama 65); B grubunun puanları 20, 30, 40 (ortalama 30) iken A\'dan 50 puanlı kişi B\'ye geçiyor. Taşınmadan sonra iki grubun ortalaması nasıl değişir?', 'İkisinin ortalaması da artar', ['A\'nınki artar, B\'ninki azalır', 'İkisinin ortalaması da azalır', 'İkisinin ortalaması da değişmez'], 'A: (60+70+80)/3 = 70; B: (20+30+40+50)/4 = 35. Hiçbir kişinin puanı değişmemesine rağmen iki grup ortalaması yükselir; bu, Will Rogers fenomenidir ve ortalamaya bakarak \'iyileşme\' demenin riskini gösterir.'),
  ('Bir hastalığın evreleme ölçütleri duyarlı bir tarama ile değiştiriliyor ve bazı hastalar daha hafif evreden daha ağır evreye yeniden sınıflandırılıyor. Her iki evrenin sağ kalım oranı da yükseliyor, oysa hiçbir hasta daha uzun yaşamıyor. Bu görünümün ismi nedir?', 'Evre kayması', ['Simpson paradoksu, yani alt grup oranlarının tersine dönmesi', 'Ekolojik yanılgı', 'Kumarbaz yanılgısı'], 'Sınıflandırma değişince, ağır evrenin en hafifleri hafif evrenin en ağırları gibi davranır ve iki ortalama birden artar. Aslında kimsenin sağ kalımı değişmemiştir.'),
  ('Bir hastanede yeni bir tarama programı başlatıldıktan sonra o hastalığa \'yeni tanı konan\' hasta sayısı artıyor. Bu durumda hastalığın gerçek sıklığının arttığı sonucuna varmak için hangi bilgi gereklidir?', 'Taramasız karşılaştırma verisi', ['Hastanenin kaç yataklı olduğu', 'Hastaların hangi ilçeden geldiği', 'Tarama cihazının üretim yılı'], 'Tarama, belirti vermeyen vakaları da bulduğundan tanı sayısını artırır. Gerçek sıklık artışı için taramadan bağımsız ölçüm (ör. ölüm kayıtları, tarama yapılmayan bölgeler) gerekir.'),
  ('Bir şirket, kullanıcıların izniyle toplanmış konum verilerini aynı kullanıcıları belirlemeyecek biçimde yayımlıyor; ancak bir araştırmacı, evden işe giden iz örüntüleriyle kişileri belirleyebiliyor. Bu örnekte asıl sorun nedir?', 'İz verisinin kendisinin ayırt edici olması', ['Verinin çok küçük bir örneklemi kapsaması, çünkü veri çok büyüktür', 'Konum bilgisinin hiçbir zaman sayılamaması', 'Kullanıcıların verilere ulaşamaması'], 'Rutin hareket örüntüleri neredeyse parmak izi gibi ayırt edicidir. Adı çıkarılmış veri, yüksek boyutlu ayırt edici örüntüler taşıyorsa anonim sayılamaz.'),
  ('Genç nüfusu çoğunlukta olan X ülkesinde nüfusun %80\'i gençtir (yıllık ölüm oranı %1), %20\'si yaşlıdır (%10). Y ülkesinde nüfusun %40\'ı genç (%0,5), %60\'ı yaşlıdır (%8). Hangi ülkenin ham ölüm oranı daha yüksektir ve bu neyi gösterir?', 'Y\'ninki (%5\'e karşı %2,8); Y daha yaşlı bir nüfustur', ['X\'inki (%2,8\'e karşı %5); çünkü her yaşta ölüm oranı X\'te daha yüksektir', 'İkisinin ham oranı eşittir; çünkü yaş yapısının ölüm oranına etkisi yoktur', 'Hesaplanamaz; çünkü nüfus büyüklükleri verilmemiştir'], 'X: 0,8 × 1 + 0,2 × 10 = %2,8; Y: 0,4 × 0,5 + 0,6 × 8 = %5. Y her yaş grubunda daha sağlıklı olsa bile yaşlı oranı yüksek olduğu için ham oran büyüktür; karşılaştırmada yaş standardizasyonu gerekir.'),
  ('Yaş, dönem ve kohort etkilerini birlikte modellemek isteyen araştırmacılar hangi temel kimliklendirme sorunuyla karşılaşır?', 'Üç etki birbirinden tek başına ayrıştırılamaz', ['Üç değişkenin hiçbir zaman sayısal olmaması', 'Her üç etkinin her zaman sıfır olması', 'Üç etkinin yalnızca iki ölçümle hesaplanabilmesi'], 'Üç değişken arasında kesin bir doğrusal ilişki bulunduğundan, ek varsayımlar olmadan etkilerin ayrıştırılması mümkün değildir. Bu, yaş-dönem-kohort analizinin klasik sorunudur.'),
  ('Bir veri analisti, 20 gözlem ve 500 değişkenden oluşan bir veri kümesinde en güçlü ilişkiyi veren değişkenleri tarayıp \'en önemli yordayıcılar\' olarak raporluyor. Bu yaklaşımın en önemli riski nedir?', 'Şansla güçlü görünen sahte örüntüler seçilir', ['Değişken sayısının fazla olması sonuçları her zaman doğru kılar', 'Gözlem sayısının az olması güvenilirliği artırır', 'İlişkiler yalnızca sayısal olmayan veriyle bulunabilir'], 'Çok sayıda aday değişken ve az gözlem olduğunda, yalnızca şansla güçlü görünen ilişkiler bulunur. Yeni verilerde doğrulanmayan bu ilişkiler, aşırı uyum ürünüdür.'),
  ('Bir şehir 2023\'te \'şimdiye kadarki en yüksek sıcaklık rekoru\' kırdığını duyuruyor. Bağımsız ve aynı dağılımlı yıllık en yüksek sıcaklık verisi için, n. yılda yeni bir rekor görülme olasılığı nedir?', '1/n', ['Her yıl %50', 'Her yıl %1', 'n. yılda n/100'], 'Aynı dağılımlı bağımsız gözlemlerde, n. gözlemin ilk n gözlem içinde en büyük olma olasılığı simetri gereği 1/n\'dir. Rekorlar zamanla seyrekleşir; sık rekorlar bir eğilim işaret eder.'),
  ('2013\'te bir öğrenci, ünlü bir kamu borcu ve büyüme çalışmasında, hesap çizelgesindeki bir hücre aralığı hatası nedeniyle beş ülkenin ortalamaya dahil edilmediğini fark etti. Bu olay hangi pratiğin önemini gösterir?', 'Yeniden üretilebilir paylaşımı', ['Hiçbir zaman ortalama hesaplanmamasını', 'Yalnızca büyük ülkelerin veri sayılmasını', 'Hesapların kâğıt üzerinde yapılmasını'], 'Veri ve hesap adımları paylaşılırsa hatalar daha hızlı bulunur. Tek bir hücre aralığı hatası, politika tartışmalarını etkileyen sonuçları değiştirebilir.'),
  ('Chapman ve Chapman\'ın 1967 deneyinde katılımcılara, hastaların çizimleri ile belirtileri rastgele eşleştirilerek gösterildi. Katılımcılar, rastgele eşleşmelere rağmen \'şüpheci kişiler gözleri büyük çizer\' gibi sezgisel ilişkileri veride gördüklerini bildirdi. Bu olgunun adı nedir?', 'Yanılsamalı korelasyon', ['Simpson paradoksu, çünkü alt gruplar tersine döner', 'Ortalamaya dönüş, çünkü uç değerler sonra normale yaklaşır', 'Büyük sayılar yasası, çünkü oranlar sabitlenir'], 'Önceki inançlar, ilişkisiz verilerde bile bir ilişki görmeyi kolaylaştırır. Beklenti, uyumlu örnekleri akılda tutarken uyumsuzları unutturur.'),
  ('1900\'lerin başında \'Akıllı Hans\' adlı at, sahibinin sorularına toynağıyla vurarak toplama-çıkarma sonuçlarını bildiriyordu. Oskar Pfungst, atın yanıtlarını soruyu soranın farkında olmadan verdiği küçük ipuçlarından çıkardığını gösterdi. Bu olay deneylerde hangi sorunun örneğidir?', 'Gözlemcinin beklentisinin sonuçları istemsizce yönlendirmesi', ['Örneklemenin sınırlı büyüklüğü, çünkü tek at test edilmiş', 'Ortalamaya dönüş, çünkü at zamanla normale yaklaşır', 'Sürücüsünün hiçbir zaman bulunmayışı, çünkü at yalnız çalışmış'], 'Soruyu soran kişi doğru yanıta yaklaşırken gerilimini değiştirdi ve at bunu fark etti. Çift kör tasarımlar, deneycinin beklentisinin sonuçlara sızmasını önler.'),
  ('Bir araştırmacı, test edilen 300 hastanın hiçbirinde yan etki görmeden \'ilacın yan etkisi yoktur\' sonucuna varıyor. Üç kuralına göre bu gözlem, yan etki olasılığının gerçekte en fazla yaklaşık ne kadar olabileceğini gösterir?', 'Yaklaşık %1', ['Tam olarak %0', 'Yaklaşık %10', 'Yaklaşık %30, çünkü gözlenen oran sıfırdır'], '300 gözlemde hiç olay görülmemesi, %95 güvenle gerçek oranın yaklaşık 3/300 = %1\'den küçük olduğunu söyler. \'Görülmedi\' ifadesi \'yok\' anlamına gelmez; küçük olasılıklı yan etkiler daha büyük örneklem gerektirir.'),
  ('Bir araştırmacı, \'Her mahallede kişi başına gelir ortalaması yükselmiştir; o hâlde kentin bütününde de yükselmiştir\' diyor. Bu çıkarımın hangi durumda yanlış çıkabileceğini gösteren olgu hangisidir?', 'Simpson paradoksu; toplam ortalama bileşimle azalabilir', ['Büyük sayılar yasası; örneklem büyüdükçe oran sabitlenir', 'Çıpalama; rakamlar ilk görülene yakınsar', 'Kümelenme yanılsaması; gürültüde örüntü görülür'], 'Nüfusun dağılımı düşük gelirli mahallelere kayarsa, her mahallede ortalama artarken kent ortalaması düşebilir. Alt grup ve toplam yorumları birlikte değerlendirilmelidir.'),
  ('Bir şirkette erkek çalışanların ortalama maaşı kadın çalışanlarınkinden yüksektir; ancak her departmanda kadınların ortalama maaşı erkeklerinkinden yüksektir. Bu durum nasıl açıklanır?', 'Erkekler yüksek maaşlı departmanlarda yoğunlaşmıştır', ['Hesaplamalar tutarsızdır ve biri kesinlikle yanlıştır', 'Maaşlar rastgele atanmaktadır', 'Departman bilgisi hiçbir zaman toplam ortalamayı etkilemez'], 'Toplam ortalama, departman büyüklükleriyle ağırlıklandırılmış bir ortalamadır. Erkeklerin yüksek ücretli departmanlara yığılması toplamda tersine bir tablo yaratabilir.'),
  ('Bir havayolu iki sefer yapıyor: kapasitesi 100 olan birinde 100 yolcu, diğerinde 20 yolcu var; yönetim \'ortalama doluluk %60\' diyor. Yolcuların kendi deneyimledikleri ortalama doluluk bundan nasıl farklıdır?', 'Daha yüksektir, yaklaşık %87; yolcuların çoğu dolu seferde bulunur', ['Daha düşüktür, yaklaşık %20; çünkü yolcuların çoğu boş seferde bulunur', 'Aynıdır, çünkü sefer sayısına bakılır', 'Daha düşüktür, yaklaşık %40; çünkü yolcu sayısı eşit alınır'], 'Yolcu ağırlıklı doluluk (100 × 1 + 20 × 0,2) / 120 ≈ 0,87\'dir. Kalabalık seferde daha çok kişi bulunduğundan, yolcu deneyimi sefer ortalamasından yüksektir.'),
  ('Bir hastanede belirli bir günde yatmakta olan hastaların ortalama yatış süresi, o hastaneden yıl boyunca taburcu olan hastaların ortalama yatış süresinden genellikle nasıl farklıdır?', 'Daha uzundur; uzun yatanlar bir günde daha sık yakalanır', ['Daha kısadır; çünkü kısa yatanlar bir günde daha çok görünür', 'Aynıdır; çünkü iki grup aynı hastalardan oluşur', 'Hesaplanamaz; çünkü yatış süresi bir günde ölçülemez'], 'Anlık bir kesit, uzun süre yatanları orantısız biçimde yakalar (süre yanlılığı). Bu yüzden anlık kesit ortalaması, taburculuk ortalamasından büyüktür.'),
  ('Bir klinik çalışmada kontrol grubundaki katılımcılar, kendilerinin \'tedavi görmeyen grup\' olduğunu öğrenince daha çok çaba gösterip kendi başlarına önlem alıyor ve gruplar arasındaki fark küçülüyor. Bu olgunun adı nedir?', 'John Henry etkisi', ['Hawthorne etkisi, çünkü gözlenenler yalnız ilgi görmek için davranır', 'Plasebo etkisi, çünkü hastalar şeker hapına inanır', 'Kayıptan kaçınma, çünkü kayıp kazançtan ağır gelir'], 'Kontrol grubu, gerilik hissiyle daha çok çabalayarak farkı yapay biçimde küçültür. Bu, kontrol grubunun davranışının tedavi etkisini maskelediği bir tasarım sorunudur.'),
  ('2001\'de yapılan bir çalışma, Oscar kazanan oyuncuların kazanmayanlardan ortalama yaklaşık 4 yıl daha uzun yaşadığını bildirdi. Sonraki eleştiriler, ödülü almak için yaşamak gerektiğinden \'ölümsüz zaman yanlılığı\' bulunduğunu savundu. Bu eleştirinin özü nedir?', 'Ödül öncesi yaşam süresi ödüllü grubun lehine sayılıyor', ['Ödülün gerçekten ömrü uzattığı kesin olarak kanıtlandığı için', 'Oyuncuların ödülden hemen sonra ölmesi gerektiği için', 'Ödül töreninin her zaman kış aylarında yapılması gerektiği için'], 'Ödülü alabilmek için belirli bir süre hayatta kalmak gerekir; bu süre \'ölümsüz zaman\' olarak ödüllü grubun lehine sayılır. Zamanla değişen maruziyetler uygun yöntemlerle çözümlenmelidir.'),
  ('Bir şirket, çalışanlarının işe girdikten sonra ilk üç ayda aldığı eğitimi \'başarılı\' bulup, aynı dönemde işten ayrılanları ve eğitimi tamamlamayanları analizden çıkarıyor. Sonuçların \'eğitim sonrası performans yüksek\' çıkması neden şaşırtıcı değildir?', 'Analiz, başarılı kalan çalışanlarla sınırlıdır', ['Eğitim her zaman performansı artırır', 'Performans ölçümü yalnızca eğitimle belirlenir', 'Ayrılanların performansı her zaman yüksektir'], 'Eğitimi tamamlamayanlar ve ayrılanlar dışlandığında, geriye kalanlar zaten daha uyumlu ve başarılı kişilerdir. Bu bir hayatta kalma yanlılığıdır.'),
  ('Epidemiyolog Bradford Hill\'in 1965\'te önerdiği nedensellik ölçütleri arasında, sonuç gerçekten nedensel ise mutlaka sağlanması gereken tek ölçüt hangisidir?', 'Zamansallık: neden, sonuçtan önce gelmelidir', ['Özgüllük: her neden yalnız tek bir sonuca yol açmalıdır', 'Analoji: benzer bir ilişki başka bir alanda da bulunmalıdır', 'Tutarlılık: ilişki her koşulda tamamen aynı büyüklükte çıkmalıdır'], 'Nedenin sonuçtan önce gelmesi zorunludur; öbür ölçütler destekleyici olsa da zorunlu değildir. Örneğin bir neden birden çok sonuca yol açabilir.'),
  ('Randomize bir çalışmada bazı hastalar atandıkları tedaviyi bırakıyor. \'Yalnızca tedaviyi tamamlayanları\' analiz etmek neden yanlıdır?', 'Tamamlayanlar rastgele seçilmemiştir; denge bozulur', ['Tedaviyi tamamlayan hastaların sayısı her zaman çok fazla olur', 'Tamamlayanların verilerinin ölçülememesi nedeniyle analiz yapılamaz', 'Tedaviyi bırakanlar her zaman iyileşmiş sayılır'], 'Tedaviyi bırakma kararı hastanın durumuyla ilişkili olabilir; bu yüzden yalnız uyum gösterenleri analiz etmek, rastgele atamanın sağladığı dengeyi bozar. Niyet-tedavi analizi, atanan gruba göre analiz eder.'),
  ('Bir çalışma \'ilaç, ölüm ya da hastaneye yatış ya da kalp krizinden oluşan bileşik sonuç riskini %20 azalttı\' bildiriyor. Sonuçların ayrıntısında ölüm sayıları iki grupta aynı, azalma yalnızca hastaneye yatışta. Bileşik sonucun sorunu nedir?', 'Küçük bileşenler ağırı gizleyebilir', ['Bileşik sonuçlar her zaman ölümü de azaltır', 'Bileşik sonuçlar yalnız kontrol grubunda hesaplanır', 'Bileşik sonuç hiçbir zaman ayrı bileşenlere ayrılamaz'], 'Azalma, daha sık ama daha az önemli olan olaylardan geliyor olabilir. Her bileşenin ayrı raporlanması, ağır sonuçlardaki gerçek etkiyi gösterir.'),
  ('Bir sağlık kuruluşu \'hastalığa yakalananların %80\'i aşısızdı\' diyor. Nüfusun %90\'ı aşılıdır. Bu bilgiyle aşının etkililiği hakkında ne söylenebilir?', 'Aşı güçlü biçimde korur', ['Aşı etkisizdir, çünkü hastaların çoğu aşısızdır', 'Aşı zararlıdır, çünkü aşılılar daha çok hastalanır', 'Hiçbir sonuç çıkarılamaz, çünkü oran hesaplanamaz'], 'Nüfusun yalnız %10\'u aşısızken hastaların %80\'inin aşısız olması, aşısızlarda riskin çok yüksek olduğunu gösterir. Bu durumda aşısızlarda risk, aşılılara göre yaklaşık 36 kat yüksektir.'),
  ('Bir yatırım her dönem eşit olasılıkla %60 kazandırıyor ya da %40 kaybettiriyor. Bir dönemde kazanç, bir dönemde kayıp yaşayan yatırımcının iki dönem sonundaki parası ilk değerine göre nasıl değişir?', '%4 azalır', ['%20 artar, çünkü beklenen getiri pozitiftir', 'Hiç değişmez, çünkü kazanç ve kayıp birbirini götürür', '%10 artar, çünkü ortalama getiri %10\'dur'], '1,6 × 0,6 = 0,96\'dır; yani %4 kayıp. Her dönem beklenen getiri %10 olsa da, çarpımsal bileşik getiri uzun vadede daha düşüktür.'),
  ('Bir fiyat endeksi her yıl aynı ürün sepetinin maliyetini ölçüyor. Tüketiciler pahalanan ürünü bırakıp ucuzlayan ürüne yöneldiğinde, sabit sepetli endeks için ne beklenir?', 'Yaşam maliyeti artışını abartır', ['Yaşam maliyeti artışını olduğundan az gösterir', 'Yaşam maliyeti artışını tam olarak gösterir', 'Yaşam maliyetini hesaplayamaz'], 'Sabit sepet, tüketicinin ikame davranışını yok sayar; pahalanan ürünü sepetten çıkarmaz. Bu nedenle enflasyon biraz abartılabilir (ikame yanlılığı).'),
  ('Bir bahis sitesi iki eşit güçte takımın maçında her iki sonuca da 1,90 ondalık oran veriyor. Oranlardan çıkarılan örtük olasılıkların toplamı kaçtır ve bu neyi gösterir?', 'Yaklaşık %105; sitenin kâr marjı eklenmiştir', ['Tam %100; çünkü iki sonucun olasılığı 1\'dir', 'Yaklaşık %95; çünkü oranlar tersine çevrilmiştir', 'Yaklaşık %50; çünkü yalnız bir sonuç sayılır'], 'Örtük olasılık 1 / 1,90 ≈ %52,6\'dır ve iki sonuç için toplam yaklaşık %105,3 olur. %100\'ü aşan kısım, bahis sitesinin marjıdır; uzun vadede oyuncunun beklenen kaybıdır.'),
  ('Bir seçim öncesinde 10 farklı anket yayımlanıyor ve hepsi aynı kayıtlı seçmen listesinden örnekleme yapıyor. Bu 10 anketin ortalaması alınırsa hangi hata türü azalmaz?', 'Ortak çerçeveden gelen sistematik hata', ['Her anketin kendi rastgele örnekleme hatası', 'Anketlerdeki tüm hatalar kesinlikle sıfırlanır', 'Yalnız soru metnine bağlı hatalar yok olur'], 'Bağımsız rastgele hatalar ortalamada azalır; fakat bütün anketler aynı yönde yanlıysa, ortalama da aynı sapmayı taşır. Anket birleştirmesi sistematik hatayı çözmez.'),
  ('Bir araştırma, iki grup arasındaki farkın güven aralığını [−2; +14] puan olarak bildiriyor ve \'fark yoktur\' diyor. Bu aralık hakkında hangisi doğrudur?', 'Sıfırı içerir ama büyük farkı da dışlamaz', ['Aralık sıfırı içerdiğinden fark kesinlikle sıfırdır', 'Aralık sıfırı içermediğinden fark çok büyüktür', 'Aralığın genişliği sonucu daha kesin kılar'], 'Geniş bir aralık, gerçek farkın hem sıfırı hem de büyük pozitif değerleri kapsayabildiğini gösterir. Anlamsız sonuç, etkisizliğin kanıtı değildir.'),
  ('Bir araştırmacı, 5 kişiden her birinde 10\'ar kez ölçüm alıp toplam 50 ölçümü \'n = 50 bağımsız gözlem\' kabul ederek analiz ediyor. Bu analizin sorunu nedir?', 'Ölçümler bağımlıdır; etkili örneklem 5\'e yakındır', ['50 ölçüm yetersiz sayıda ölçümdür ve hiçbir sonuç vermez', 'Ölçümlerin on tane olması ölçeklenemez', 'Beş kişi hiçbir zaman ölçülemez'], 'Aynı kişiden alınan tekrarlı ölçümler benzerdir; bunları bağımsız saymak anlamlılığı şişirir (sahte tekrar). Analizde kişi düzeyinde değişkenlik hesaba katılmalıdır.'),
  ('Bir deneyde her biri 3 hayvandan oluşan iki grup vardır ve her hayvandan 20 hücre ölçülmüştür; analizde 60 ve 60 hücre bağımsız sayılmıştır. Bu uygulama sonucu nasıl etkiler?', 'Anlamlılık olduğundan güçlü görünür', ['Anlamlılık olduğundan zayıf görünür', 'Sonuç değişmez; hücre sayısı belirleyicidir', 'Analiz hiçbir sonuç veremez'], 'Aynı hayvandan gelen hücreler birbirine bağımlıdır. Bağımsız deneysel birim hayvan olduğundan, hücreleri birim saymak yanlış pozitif oranını artırır.'),
  ('Bir kentte trafik kazalarında ölenlerin sayısı son yıl %10 azalıyor ancak toplam araç-kilometre %20 artıyor. Araç-kilometre başına ölüm oranı için hangisi doğrudur?', 'Yaklaşık %25 azalmıştır', ['%10 azalmıştır, çünkü araç-km artışı hesaba katılmaz', '%10 artmıştır', '%20 azalmıştır'], '0,90 / 1,20 = 0,75\'tir; yani oran %25 azalmıştır. Ölüm sayısı ile maruz kalma ölçüsü (araç-km) birlikte değerlendirilmelidir.'),
  ('1854 Londra kolera salgınında John Snow, aynı mahallelerde birbirine karışık yaşayan ve su aldıkları şirket dışında benzer haneleri karşılaştırdı: Southwark & Vauxhall su şirketi müşterilerinde ölüm oranı çok yüksek, Lambeth şirketi müşterilerinde çok düşüktü. Bu karşılaştırmanın gücü nereden geliyordu?', 'Haneler benzerdi', ['Haneler zengin ve fakir diye ayrılmıştı', 'Ölümlerin kaydı tutulmamıştı', 'Lambeth müşterileri yalnızca gönüllüydü'], 'Su kaynağı, hane özelliklerinden büyük ölçüde bağımsız dağılmıştı; bu, doğal deneye benzer bir karşılaştırma yarattı. Böylece karıştırıcılar dengelenmiş, su kaynağı ile hastalık arasındaki ilişki güçlenmişti.'),
  ('Hemşire sağlığı çalışması gibi gözlemsel araştırmalar, menopoz sonrası hormon tedavisi kullanan kadınlarda kalp hastalığının daha az olduğunu bildirmişti; 2002\'de rastgele atamalı bir deneyde (WHI) tedavinin kalp hastalığı riskini azaltmadığı, hatta artırabildiği görüldü. Bu çelişki en çok neye bağlanır?', 'Kullananların daha sağlıklı olması', ['Rastgele atamalı deneylerin hiçbir zaman güvenilir olmaması', 'Kalp hastalığının yalnız hormonlarla ilişkili olması', 'Kadınların deneylere hiç katılmaması'], 'Gözlemsel çalışmalarda tedavi seçen kadınlar, sağlık davranışları ve gelir bakımından farklıydı (sağlıklı kullanıcı yanlılığı). Rastgele atama bu karıştırıcıları dengeledi.'),
  ('1990\'larda yapılan CARET çalışmasında beta-karoten takviyesi alan sigara içenlerde akciğer kanseri oranının arttığı görüldü; oysa gözlemsel çalışmalar beta-karotenden zengin beslenenlerde kanserin daha az olduğunu göstermişti. Bu çelişki neyi hatırlatır?', 'İlişki takviyeye dönüşmeyebilir', ['Beslenmenin kansere hiçbir etkisi olmadığını', 'Sigara içenlerin deneylere katılamayacağını', 'Beta-karotenin yalnız yemekten alınamayacağını'], 'Karotenden zengin beslenenler ayrıca başka sağlıklı alışkanlıklara sahiptir. Besinden elde edilen madde ile saf takviyenin etkisi farklı olabilir.'),
  ('1950\'lerde başlayan İngiliz doktorlar çalışmasında yaklaşık 40 bin doktor yıllarca izlendi ve sigara içenlerde akciğer kanseri ölümlerinin daha çok olduğu görüldü. Bu tasarımın, sigara içenleri ve içmeyenleri tek zamanda karşılaştıran bir kesit çalışmaya göre üstünlüğü nedir?', 'Zaman sırası sağlanır', ['Katılımcıların hiçbir karıştırıcı taşımaması', 'Sonuçların kısa sürede alınması', 'Doktorların sigara içmemesi'], 'İleriye dönük izlemede maruziyet, hastalıktan önce kaydedilir; bu, nedensellikte zaman sırası için önemlidir. Karıştırıcılar hâlâ bulunabilir ancak ters nedensellik olasılığı azalır.'),
  ('Joseph Goldberger, 1910\'larda pellagra hastalığının bulaşıcı olduğu görüşüne karşı, hastalığın yoksul ve kötü beslenen kesimlerde yoğunlaştığını gösterdi. \'Kötü hijyen pellagraya yol açar\' görüşünü zayıflatan en güçlü bulgu hangisidir?', 'Beslenme düzelince hastalık azaldı', ['Hastaların daha çok yaşlı olması', 'Hastalığın yalnız şehirlerde görülmesi', 'Doktorların hastalığı kayda geçirmemesi'], 'Yoksulluk, hem kötü hijyeni hem yetersiz beslenmeyi birlikte getiren bir karıştırıcıydı. Beslenmeyi tek başına değiştiren müdahale, asıl nedeni ayırt etti.'),
  ('Kahneman\'ın aktardığı bir olayda, bir ders programı geliştiren ekip kendi sürelerini 1,5 ile 2,5 yıl arası tahmin etti; benzer projelerin geçmiş süreleri sorulunca yaklaşık yarısının hiç bitmediği ve bitenlerin 7 ila 10 yıl sürdüğü öğrenildi. Bu olay hangi eğilimi gösterir?', 'Planlama yanılgısı; taban oranı göz ardı edilir', ['Kayıptan kaçınma; kayıpların ağır gelmesi', 'Çıpalama; ilk rakama yakın kalma', 'Sonradan bilme yanlılığı; sonuçların kolayca öngörülmesi'], 'Ekipler kendi projelerinin ayrıntılarına odaklanıp benzer projelerin gerçek başarı ve süre dağılımını göz ardı eder. Referans sınıfı tahmini (dış bakış), bu yanılgıyı azaltır.'),
  ('Florida\'da 1970\'lerde işlenen cinayetlerin bir veri kümesinde, toplamda beyaz sanıkların ölüm cezası alma oranı (%11,9) siyah sanıklarınkinden (%10,2) biraz yüksekti. Kurbanın ırkına göre ayrıldığında ise her iki kurban grubunda da siyah sanıkların oranı daha yüksek çıktı. Bu durum hangi olgunun örneğidir?', 'Simpson paradoksu', ['Ekolojik yanılgı, çünkü grup düzeyinden bireye geçilmiştir', 'Yayın yanlılığı, çünkü olumlu sonuçlar seçilmiştir', 'Kumarbaz yanılgısı, çünkü art arda sonuçlar beklenmiştir'], 'Sanık ve kurban ırkı birbiriyle yakından ilişkiliydi; bu karıştırıcı toplam oranın yönünü tersine çevirdi. Alt grup düzeyinde gözlenen fark, toplamdaki farkın tam tersiydi.'),
  ('Bir ülkede enflasyon yıllık %50\'dir. Aylık enflasyon bileşik olarak sabit kabul edilirse, aylık fiyat artışı yaklaşık kaçtır?', 'Yaklaşık %3,4', ['Yaklaşık %4,2, çünkü yıllık oran 12\'ye bölünür', 'Yaklaşık %5, çünkü aylık oran yıllığın onda biri alınır', 'Yaklaşık %2,5, çünkü yıllık oran 20\'ye bölünür'], '1,5^(1/12) ≈ 1,034\'tür. Yıllık oranı 12\'ye bölmek (%4,17) bileşik büyümeyi hesaba katmaz.'),
  ('1933\'te Horace Secrist \'Ortalamalığın Zaferi\' adlı kitabında, ilk yıllarda en kârlı olan işletmelerin kârlarının sonraki yıllarda ortalamaya yaklaştığını ve rekabetin işletmeleri ortalamalaştırdığını savundu. İstatistikçi Harold Hotelling bu sonucu nasıl eleştirdi?', 'Uç gruplarda ortalamaya dönüş kaçınılmazdır', ['Ortalamaya dönüşün hiç yaşanmadığı ve verinin uydurma olduğu', 'İşletmelerin hep aynı kârı koruduğu', 'Kâr verisinin yalnız bir yılla sınırlı kalması gerektiği'], 'Önce uç değerlere göre grup seçip sonra onları izleyen herhangi bir veri, ortalamaya doğru çekilmiş görünür. Bu bir istatistik yapıdır; rekabetin yarattığı yakınsama anlamına gelmez.'),
  ('Bir araştırmada geniş bir genetik taramadan çıkan en güçlü \'keşif\' sinyali, ikinci bağımsız örneklemde belirgin biçimde zayıf çıkıyor. Bu durum için hangi kavramlar en uygundur?', 'Kazananın laneti ve ortalamaya dönüş', ['Hayatta kalma yanlılığı ve Simpson paradoksu', 'Sosyal beğenirlik ve çıpalama', 'Kumarbaz yanılgısı ve savcı yanılgısı'], 'Binlerce aday arasından en güçlü olanı seçmek, şans payını da seçmektir. Bağımsız örneklemde bu şans payı tekrarlanmadığı için etki küçülür.'),
  ('1990\'larda bir grup, Tevrat metninde belirli aralıklarla harf atlayarak (\'eşit aralıklı harf dizileri\') tarihsel olayların \'önceden bildirildiğini\' savundu. Başka araştırmacılar aynı yöntemle bir Amerikan romanında da benzer \'kehanetler\' buldu. Bu karşılaştırma neyi gösterdi?', 'Büyük metinde her yerde örüntü bulunur', ['Romanın da gizli kehanetler taşıdığını', 'Harflerin hiçbir zaman rastgele dağılmadığını', 'Metin uzunluğunun örüntü bulmayı engellediğini'], 'Sonsuz sayıda seçenek (aralık, başlangıç, kelime) arasından anlamlı görüneni seçmek, Texas keskin nişancı yanılgısıdır. Kontrol metni de aynı örüntüleri üretince bu bulgu anlamsızlaşır.'),
  ('Bir ankette katılımcıların \'Hiç yasadışı madde kullandınız mı?\' sorusuna dürüst yanıt vermesini sağlamak için \'rastgele yanıt tekniği\' kullanılıyor: katılımcı gizlice para atıyor; yazı gelirse doğruyu söylüyor, tura gelirse ikinci kez atıp yazıysa \'evet\', turaysa \'hayır\' diyor. Katılımcıların %40\'ı \'evet\' dediyse gerçek \'evet\' oranı yaklaşık kaçtır?', '%30', ['%40, çünkü yanıtlar doğrudan alınır', '%15, çünkü yarısı rastgele yanıtlar', '%20, çünkü kalan yüzde ikiye bölünür'], 'P(evet) = 0,5 × p + 0,5 × 0,5 = 0,5p + 0,25 olduğundan 0,40 = 0,5p + 0,25 ve p = 0,30\'dur. Bireyin yanıtı gizli kalırken, grup oranı tahmin edilebilir.'),
  ('Bir hastanede yapılan tıbbi bir testin sonucu \'%95 doğru\' diye duyuruluyor ve 1000 kişi test ediliyor; bunların 50\'si gerçekten hasta. Test hastaların %95\'ini doğru buluyor ve sağlıkların %95\'ini doğru buluyor. Pozitif çıkan kişilerin yaklaşık kaçta kaçı gerçekten hastadır?', 'Yaklaşık yarısı', ['Yaklaşık %95\'i, çünkü test %95 doğrudur', 'Yaklaşık %5\'i', 'Yaklaşık %80\'i'], 'Hastaların 47,5\'i, sağlıklıların ise 950 × 0,05 = 47,5\'i pozitif çıkar; pozitiflerin yaklaşık yarısı hastadır. Yüksek doğruluk, hastalık nadir olduğunda pozitif öngörü değerini düşük bırakabilir.'),
  ('\'Boy %80 kalıtsaldır\' ifadesini \'bir kişinin boyunun %80\'i genlerinden gelir\' diye yorumlamak neden yanlıştır?', 'Kalıtım oranı varyans payını anlatır', ['Boyun hiçbir şekilde kalıtsal olmaması', 'Kalıtım oranının yalnızca erkeklerde hesaplanması', 'Genlerin boyu hiç etkilememesi'], 'Kalıtım oranı, belirli bir topluluk ve ortamda gözlenen farkların ne kadarının genetik farklara bağlı olduğunu söyler. Bireysel bir özelliğin yüzde kaçının gen kaynaklı olduğunu söylemez.'),
  ('Bir özellik için kalıtım oranı çok yüksek bulunmuştur. Bu bilgi, özelliğin çevresel müdahalelerle değiştirilemeyeceği anlamına gelir mi?', 'Hayır; kalıtım oranı, müdahaleyle değişebilirliği anlatmaz', ['Evet; yüksek kalıtım oranı değişmezlik demektir', 'Evet; yalnızca ortalama değiştirilebilir', 'Hayır; çünkü kalıtım oranı hiçbir özellik için hesaplanamaz'], 'Kalıtım oranı yüksek bir özellik (ör. miyop gözlük kullanımı) çevresel bir müdahaleyle yine de değişebilir. Oran, mevcut koşullardaki varyans paylarını yansıtır.'),
  ('Bir kentte sıcak hava dalgası sırasında ölümler belirgin biçimde artıyor. Dalga bittikten sonraki haftalarda ölüm sayıları beklenenin altına inerse bu durum ne anlama gelir?', 'Öne çekilen kırılgan kişi ölümleri', ['Sıcak hava dalgasının hiç ölüme yol açmadığı', 'Ölüm kayıtlarının yanlış tutulduğu', 'Kırılgan kişilerin hiç bulunmadığı'], 'Kırılgan kişilerin ölümü sıcaklıkla birkaç hafta öne çekilmiş olabilir; sonraki düşüş bunu telafi eder (harmanlama etkisi). Toplam etkiyi hesaplarken sonraki dönem de dikkate alınmalıdır.'),
  ('Bir genetik taramada 1000 gen sınanıyor; bunların 100\'ü gerçekten etkili, 900\'ü etkisizdir. Test gücü %80 ve anlamlılık düzeyi %5 ise \'anlamlı\' bulunan genlerin yaklaşık yüzde kaçı yanlış keşiftir?', 'Yaklaşık %36', ['Yaklaşık %5, çünkü anlamlılık düzeyi %5\'tir', 'Yaklaşık %20, çünkü güç %80\'dir', 'Yaklaşık %64, çünkü beklenen hata toplanır'], 'Etkisizlerden 900 × 0,05 = 45 yanlış pozitif, etkililerden 100 × 0,80 = 80 gerçek pozitif çıkar; yanlış keşif oranı 45 / 125 = %36\'dır. Anlamlılık düzeyi, keşiflerin yanlış olma oranına eşit değildir.'),
  ('Bir araştırmacı veri toplarken beş kez ara analiz yapıyor ve her seferinde %5 düzeyinde anlamlı çıkarsa duruyor. Hiçbir etki yokken toplam yanlış pozitif olasılığı yaklaşık kaçtır?', 'Yaklaşık %14', ['Tam %5, çünkü her bakışta %5\'tir', 'Yaklaşık %25, çünkü beş kez %5 toplanır', 'Yaklaşık %1, çünkü bakış sayısı azalttır'], 'Tekrarlanan bakışlar ve durma kuralı yanlış pozitif oranını artırır; beş bakışta yaklaşık %14 olur (bağımsız olsalardı 1 − 0,95^5 ≈ %23 olurdu). Bu yüzden analiz planı önceden belirlenmelidir.'),
  ('Bir kanser tarama programında hasta 64 yaşında tarama ile, taramasız olsaydı 68 yaşında tanı alacak ve her iki durumda da 72 yaşında ölecek. 5 yıllık sağ kalım kriteriyle iki durum nasıl değerlendirilir?', 'Taramalı \'sağ kalan\', taramasız \'ölen\' sayılır', ['Taramalı durum \'ölen\', taramasız \'sağ kalan\' sayılır', 'İkisi de \'sağ kalan\' sayılır, çünkü ikisi de 5 yıldan uzun yaşar', 'Taramanın etkisi hesaplanamaz'], 'Taramalı durumda tanıdan ölüme 8 yıl, taramasızda 4 yıl vardır; 5 yıllık sağ kalım ölçütüyle biri başarılı sayılır. Oysa ölüm yaşı değişmemiştir; bu öncül zaman yanlılığıdır.'),
  ('Ülke X\'in yaşa özgü ölüm oranları bin kişide genç grupta 2, yaşlı grupta 20; ülke Y\'nin 1 ve 15\'tir. Standart nüfusun %70\'i genç, %30\'u yaşlı ise yaşa göre standardize ölüm oranları (bin kişide) sırasıyla yaklaşık kaçtır?', 'X için 7,4; Y için 5,2', ['X için 11; Y için 8, çünkü iki ülke eşit ağırlıkla toplanır', 'X için 22; Y için 16', 'X için 5,2; Y için 7,4'], 'X: 0,7 × 2 + 0,3 × 20 = 7,4; Y: 0,7 × 1 + 0,3 × 15 = 5,2. Standart nüfus ağırlığı, ülkelerin gerçek yaş yapısı farkını ortadan kaldırır.'),
  ('Bir ilacın göreli risk azalması %25\'tir ve başlangıç riski %8\'dir. Bir hastayı olaydan korumak için kaç hastanın tedavi edilmesi gerekir?', '50', ['4, çünkü %25\'in tersi alınır', '12, çünkü %8\'in tersi alınır', '25, çünkü azalma yüzdesi tedavi sayısıdır'], 'Mutlak azalma 0,08 × 0,25 = 0,02\'dir; NNT = 1 / 0,02 = 50. Göreli azalma yüksek görünse de baz risk düşükse NNT büyük olur.'),
  ('Bir ilde ölçülen yoksulluk oranı ile okuma puanı arasındaki ilçe düzeyindeki (ekolojik) korelasyon −0,9, bireysel düzeydeki korelasyon ise −0,4 çıkıyor. Bu farkın genel nedeni nedir?', 'Ortalama bireysel değişkenliği siler', ['Bireysel veri her zaman daha güçlü ilişki verir', 'Ekolojik veri bireysel veriden hiçbir zaman farklı olmaz', 'İlçe ortalamaları hesaplanamaz'], 'Gruplara ortalama aldıkça bireyler arası gürültü sönümlenir ve ilişki güçlü görünür. Bu nedenle grup düzeyindeki ilişki, birey düzeyi için kullanılamaz (ekolojik yanılgı).'),
  ('Bir hastane sıralamasında A hastanesi ağır vakaların %70\'ini, hafif vakaların %20\'sini; B hastanesi ağır vakaların %40\'ını, hafif vakaların %50\'sini kabul ediyor. Her ağırlık düzeyinde A\'nın ölüm oranı B\'den düşüktür ama ham ölüm oranı yüksektir. Bu durumun adı nedir?', 'Simpson paradoksu', ['Hayatta kalma yanlılığı, yani her ağırlık düzeyinin ihmal edilmesi', 'Ekolojik yanılgı', 'Öncül zaman yanlılığı'], 'Ağır hasta payı yüksek olan hastanenin ham oranı, vaka karışımı nedeniyle kötü görünür. Her ağırlık düzeyinde A daha iyi olsa da toplam tersine döner.'),
  ('Bir meta-analiz, 10 küçük çalışmada ortalama etkiyi 0,60 buluyor; aynı soruyu inceleyen büyük bir çalışma ise 0,10 buluyor. Küçük çalışmaların daha büyük etki bildirmesi hangi birleşik açıklamayla örtüşür?', 'Yayın yanlılığı ve kazananın laneti', ['Büyük çalışmaların her zaman yanlış olması', 'Küçük çalışmaların her zaman daha titiz olması', 'Etkinin örneklem büyüklüğüne bağlı olarak gerçekten değişmesi'], 'Küçük çalışmalarda anlamlılık eşiğini geçmek için gözlenen etkinin büyük olması gerekir; yalnız bunlar yayımlanır. Büyük çalışma, bu seçilimden daha az etkilenir.'),
  ('Bir bankada borçlu müşterilerin %2\'si temerrüde düşüyor. Bir model, temerrüde düşecekleri %90 doğrulukla belirliyor ve müşteri başına yaklaşık bir hata yapıyor. Yalnızca \'hiç kimse temerrüde düşmez\' diyen basit bir kural ise %98 doğruluğa sahiptir. Bu karşılaştırma doğruluk için neyi gösterir?', 'Yüksek doğruluk işe yaradığını göstermez', ['Basit kural her zaman daha iyi bir modeldir', 'Doğruluk her koşulda en iyi ölçüttür', 'Temerrüt oranı doğruluğu hiç etkilemez'], 'Nadir bir olayda hep \'olmaz\' demek yüksek doğruluk verir ama hiçbir yararı yoktur. Duyarlılık ve pozitif öngörü gibi ölçütler birlikte değerlendirilmelidir.'),
  ('Aynı yılda doğan 1000 çocuğun 12\'si belirli bir hastalıkla tanı alıyor; bir sonraki yıl tarama programı başladı ve doğan 1000 çocuğun 20\'si tanı aldı. Hastalığın gerçekten arttığını söylemek için hangi ek bilgi gerekir?', 'Taramasız tanı alıp almayacakları', ['Çocukların hangi mevsimde doğduğu, çünkü hastane büyüklüğü belirler', 'Hastanenin kaç yataklı olduğu', 'Anne babaların mesleği'], 'Tarama, belirtisiz vakaları da bulduğundan tanı sayısı artar. Gerçek artış için taramadan bağımsız bir gösterge ya da taramasız karşılaştırma bölgeleri gerekir.'),
  ('Bir tıbbi çalışmada hastalık durumu, %10\'u rastgele yanlış sınıflandırılan bir testle belirleniyor ve hata maruziyet gruplarında aynı oranda. Bu durum maruziyet ile hastalık arasındaki gerçek ilişkiyi genellikle nasıl etkiler?', 'İlişkiyi gerçekte olduğundan zayıf gösterir', ['İlişkiyi gerçekte olduğundan güçlü gösterir, çünkü hatalar birikir', 'İlişkiyi hiç etkilemez, çünkü hata her iki grupta aynıdır', 'İlişkiyi her zaman ters yönde gösterir'], 'Gruplar arasında farklı olmayan rastgele yanlış sınıflandırma, ilişkiyi sıfıra (etkisizliğe) doğru çeker. Bu yüzden gerçek etkiler küçümsenebilir.'),
  ('Bir vaka-kontrol çalışmasında yalnızca hastaların maruziyeti daha çok hatırladığı için hatalı bildirim yapılıyor; sağlıklıların bildirimi doğru. Bu farklı sınıflandırma hatasının sonucu için ne söylenebilir?', 'Yön belirsizdir', ['Yanlılık her zaman ilişkiyi sıfıra yaklaştırır', 'Yanlılık hiçbir sonuç üretmez', 'Yanlılık yalnızca p-değerini değiştirir'], 'Hata gruplar arasında farklıysa, ilişkiyi sıfıra çekmek zorunda değildir; yön hatanın niteliğine bağlıdır. Rastgele (farksız) hatadan farklı bir tehlikedir.'),
  ('Bir regresyon çözümlemesinde açıklayıcı değişken (ör. günlük tuz tüketimi) tek bir günlük anketle ölçülüyor ve ölçüm hatası büyüktür. Bu durumda tahmin edilen ilişki katsayısı (eğim) için genellikle ne beklenir?', 'Gerçek eğimden sıfıra doğru küçülmüş (seyrelmiş) çıkar', ['Gerçek eğimden büyük çıkar, çünkü ölçüm hatası eğimi büyütür', 'Gerçek eğime eşit çıkar', 'Daima negatif çıkar'], 'Açıklayıcı değişkendeki rastgele ölçüm hatası, eğimi küçültür (regresyon seyrelmesi). Bu yüzden gerçek etkiler az görünebilir.'),
  ('Bir kanser tedavisini inceleyen araştırmada, \'tedavi sonrası ortalama yaşam süresi\' hesaplanırken çalışma bittiğinde hâlâ yaşayan hastalar analizden çıkarılıyor. Bu hesabın ortalama süre üzerindeki etkisi nedir?', 'Ortalama süre gerçekte olduğundan kısa çıkar', ['Ortalama süre gerçekte olduğundan uzun çıkar, çünkü yaşayanlar süreyi uzatır', 'Ortalama süre hiç değişmez', 'Ortalama süre sıfıra eşit olur'], 'Hâlâ yaşayanlar en uzun süreli hastalardır ve onları dışlamak (sansür göz ardı etme) ortalamayı aşağı çeker. Sağ kalım analizleri sansürlü gözlemleri de hesaba katmalıdır.'),
  ('Bir hisse senedi fiyat grafiğinde uzun süreli \'trend\' görülüyor. Rastgele yürüyüş modelinde (yazı-tura atışlarıyla artış-azalış) benzer uzun trendler görülür mü?', 'Evet; rastgele serilerde de görülür', ['Hayır; rastgele seriler her zaman sürekli salınır', 'Hayır; trendler yalnız gerçek nedenlerle olur', 'Evet, ancak yalnızca yüz binlerce adımdan sonra'], 'Rastgele yürüyüşte (arcsine yasası) uzun süre tek tarafta kalma şaşırtıcı biçimde olasıdır. Bu yüzden grafik \'trendleri\' gerçek neden kanıtı sayılamaz.'),
  ('Bir kişi, yazı-tura atışlarını toplam kazanç grafiği olarak izliyor ve \'hep aynı tarafta kalıyorum, şanslıyım\' diyor. Adil bir oyunda uzun vadede toplamın hangi özelliği beklenir?', 'Uzun süre tek tarafta kalabilir', ['Toplam her an sıfır etrafında salınır', 'Toplam daima yalnız pozitif olur', 'Toplam yalnızca tek adımda sıfıra döner'], 'Rastgele yürüyüşte sıfıra dönüş garantidir ancak beklenen süre çok uzundur. Uzun serilerin \'şans\' ya da \'yetenek\' izlenimi vermesi yanıltıcıdır.'),
  ('Bir yatırımcı, 1000 farklı rastgele alım-satım kuralını geçmiş verilerde deniyor ve en iyi çıkanı seçip \'kanıtlanmış strateji\' diyor. Bu stratejinin gelecekte aynı performansı göstermesi neden beklenmez?', 'En iyiyi seçmek aşırı uyum sağlar', ['Geçmiş veri hiçbir zaman kullanılamaz', 'Tüm kuralların aynı sonuç vermesi', 'Gelecek her zaman geçmişin aynısı olur'], 'Çok sayıda strateji denendiğinde en iyisi çoğu zaman şansla öne çıkar (geriye dönük testte aşırı uyum). Bağımsız, yeni veride sınanmadıkça sonuç güvenilmezdir.'),
  ('Bir ülkede \'toplam doğurganlık hızı\' (kadın başına çocuk sayısı) 2,1\'in altına düştüğü hâlde nüfus birkaç on yıl daha artabilir. Bunun başlıca nedeni nedir?', 'Genç kadın sayısı', ['Doğurganlık hızının ölçülememesi', 'Ölüm oranının hiçbir zaman değişmemesi', 'Doğum sayısının yalnızca göçe bağlı olması'], 'Geçmişte yüksek doğurganlık, bugün çok sayıda üreme çağındaki kadın bırakır. Doğurganlık düştüğünde bile toplam doğum sayısı bir süre yüksek kalır.'),
  ('Kilo verme çalışmasında programı yarıda bırakanların son ölçülen kiloları, sonraki aylarda da aynı kabul ediliyor (son gözlemi ileri taşıma). Bu yöntem sonucu nasıl etkileyebilir?', 'Bırakanlar kilo almış olabilir', ['Etkiyi her zaman olduğundan kötü gösterir', 'Sonucu hiçbir koşulda değiştirmez', 'Veri kaybını sıfırlar ve yanlılığı tamamen giderir'], 'Bırakanların sonraki kilo değişimi bilinmediği hâlde sabit kabul etmek gerçekçi olmayabilir. Bu varsayım, etkinin yönünü çarpıtabilir.'),
  ('Bir iş yerinde ham ücret farkının büyük kısmı, farklı işlere dağılımdan kaynaklanıyor ve ayarlı fark küçük çıkıyor. \'Ayarlı fark küçük, yani sorun yok\' demek için hangi soru sorulmalıdır?', 'Dağılım adil mi, aracı mı?', ['Ücretin sayı olup olmadığı', 'Çalışan sayısının çift olup olmadığı', 'Raporun kaç sayfa olduğu'], 'İş dağılımı karıştırıcı olabileceği gibi, eşitsizliğin bir aracı yolu da olabilir. Aracı değişkene göre ayarlamak, etkinin bir kısmını gizleyebilir.'),
  ('Bir değerin iki katına çıkıp sonra yarıya düşmesi ile yarıya düşüp sonra iki katına çıkması, yüzde değişim ölçeğinde (+%100 ve −%50) simetrik görünmez. Hangi dönüşüm bu asimetriyi gidermeye yarar?', 'Logaritmik ölçek', ['Karekök ölçeği; çünkü karekök simetri sağlar', 'Yüzde puan farkı; çünkü yüzde puan oranı gösterir', 'Hiçbir dönüşüm simetri sağlamaz'], 'log(2) = −log(1/2) olduğundan log ölçeğinde iki katına çıkış ve yarıya iniş eşit mutlak büyüklüktedir. Çarpımsal değişimler için log farkı doğal bir ölçüdür.'),
  ('Bir toplumda kalp hastalıklarından ölüm azaldıktan sonra kanserden ölenlerin payı artıyor. \'Kanser tehlikesi arttı\' yorumu için hangisi söylenebilir?', 'Risk artmamış olabilir', ['Kanserin kesin biçimde arttığı kanıtlanmıştır', 'Kalp hastalığının hiç bulunmadığı', 'Ölüm nedenlerinin hiç kaydedilmediği'], 'İnsanlar bir nedenden ölmediğinde başka nedene bağlı ölümlerin payı artar (rekabetçi riskler). Yaşa göre standardize ölüm hızı gerçek eğilimi gösterir.'),
  ('İki hakem, bir hastalığın var ya da yok olduğuna 100 vakada %90 oranında aynı yönde karar veriyor; hastalık nadir olduğundan şansla beklenen uyum %85\'tir. Şans düzeltmeli uyum (kappa) için ne söylenebilir?', 'Belirgin biçimde düşüktür', ['Düzeltilmiş uyum, ham uyumdan yüksektir', 'Düzeltilmiş uyum, ham uyumla aynıdır', 'Düzeltilmiş uyum %100\'dür'], 'Kappa = (0,90 − 0,85) / (1 − 0,85) ≈ 0,33\'tür. Nadir olaylarda yüksek ham uyum, şansla zaten beklenebilir.'),
  ('Adil bir yazı-tura oyununda sonlu bir sermayeyle oynayan oyuncu karşısında sonsuz sermayeli bir kasa vardır. Yeterince uzun oynarsa oyuncunun sonunda ne olması beklenir?', 'Sermayesi sıfırlanır', ['Sermayesi sürekli artar', 'Sermayesi hep aynı kalır', 'Kasanın sermayesi bitmek zorunda kalır'], 'Adil oyunda bile rastgele yürüyüş sonlu sınırı bir gün aşar; sonlu sermayeli oyuncu sonunda iflas eder. Sonsuz kaynak, beklenen değerden bağımsız bir avantaj sağlar.'),
  ('Bir araştırmada, çok sayıda yeni şirketin ilk yıl başarısı ile kurucunun üniversite sıralaması arasında ilişki bulunmuyor; ancak yalnızca halka arz olan şirketler incelendiğinde belirgin ilişki çıkıyor. Bu fark neye işaret eder?', 'Seçilim yapay ilişki üretebilir', ['Halka arz yalnız büyük şirketlerde olur ve her zaman ilişkiyi güçlendirir', 'Üniversite sıralaması başarıyı doğrudan belirler', 'Genel örneklemde ilişki zorunlu olarak sıfırdır'], 'Halka arza ulaşma, hem yetenek hem şansa bağlı bir seçilim süzgecidir. Bu süzgeçten geçenlerle sınırlı analizde yapay ilişkiler ortaya çıkabilir.'),
];
